      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "悲伤的新闻 和无聊的闲话"
        },
        {
          "id": "V1-02",
          "zh": "从早上就听够 真的受够啦"
        },
        {
          "id": "V1-03",
          "zh": "今天比往常更想"
        },
        {
          "id": "V1-04",
          "zh": "风吹得让人好舒服"
        },
        {
          "id": "V1-05",
          "zh": "换上快乐的心情吧"
        }
      ]
    }
  ]
}

